const { existsSync } = await import('node:fs');
const imagePath = process.env.IMAGE_PATH;
if (!imagePath) { throw new Error('IMAGE_PATH env var not set'); }
if (!existsSync(imagePath)) { throw new Error(`Image file not found: ${imagePath}`); }
globalThis.imagePath = imagePath;

const { readFileSync } = await import('node:fs');
const { PDFDocument, StandardFonts } = await import('pdf-lib');

// Read image bytes
const imageBytes = readFileSync(globalThis.imagePath);

// Create PDF document
const pdfDoc = await PDFDocument.create();
const helvetica = await pdfDoc.embedFont(StandardFonts.Helvetica);
const pngImage = await pdfDoc.embedPng(imageBytes);

// Define layout constants
const margin = 50;
const pageWidth = 612; // 8.5in * 72
const pageHeight = 792; // 11in * 72
let yPos = pageHeight - margin;

// Helper to add a new page when needed
function addPageIfNeeded(requiredSpace) {
  if (yPos - requiredSpace < margin) {
    const newPage = pdfDoc.addPage([pageWidth, pageHeight]);
    yPos = pageHeight - margin;
    return newPage;
  }
  return null;
}

// Add first page
let page = pdfDoc.addPage([pageWidth, pageHeight]);

// Render markdown (simple parser)
const markdown = `# Sample Heading\n## Subheading Example\n- First bullet item\n- Second bullet item\n\nThis is a paragraph of body text that demonstrates rendering of regular text in the PDF. It can span multiple lines and will continue onto the next page if needed.`;
const lines = markdown.split(/\n/);
for (const rawLine of lines) {
  let line = rawLine.trim();
  let fontSize = 12;
  let text = line;
  if (line.startsWith('# ')) {
    fontSize = 24;
    text = line.replace(/^#\s+/, '');
  } else if (line.startsWith('## ')) {
    fontSize = 18;
    text = line.replace(/^##\s+/, '');
  } else if (line.startsWith('- ')) {
    fontSize = 12;
    text = '\u2022 ' + line.replace(/^[-*]\s+/, '');
  }
  const lineHeight = fontSize + 4;
  addPageIfNeeded(lineHeight);
  page.drawText(text, {
    x: margin,
    y: yPos - lineHeight,
    size: fontSize,
    font: helvetica,
    color: rgb(0, 0, 0)
  });
  yPos -= lineHeight;
}

// Embed the image at the bottom of the last page (scaled to fit width)
const imgDims = pngImage.scale(0.5);
if (yPos - imgDims.height < margin) {
  page = pdfDoc.addPage([pageWidth, pageHeight]);
  yPos = pageHeight - margin;
}
page.drawImage(pngImage, {
  x: margin,
  y: yPos - imgDims.height,
  width: imgDims.width,
  height: imgDims.height
});

yPos -= imgDims.height + 20;

// Save PDF bytes
const pdfBytes = await pdfDoc.save();
globalThis.pdfBytes = pdfBytes;
